-- Orientação para cadastro de legislação geral ou vinculada.
UPDATE `guniversal_dbp`.`ajuda_transacoes`
SET
    `texto_pt` = '<p>Nesta tela você pode cadastrar uma lei geral ou uma lei vinculada a uma empresa e unidade.</p><p>Para uma lei geral, deixe Empresa e Unidade sem seleção. Para uma lei vinculada, selecione primeiro a Empresa e a Unidade e depois clique em Novo. A lei será cadastrada e vinculada automaticamente.</p><p>Não é possível cadastrar uma lei vinculada informando somente a Empresa ou somente a Unidade. Ao duplicar uma lei, informe um novo Código; a nova lei não copia automaticamente histórico, assuntos ou vínculos da lei original.</p>',
    `texto_en` = '<p>On this screen you can register a general law or a law linked to a company and unit.</p><p>For a general law, leave Company and Unit unselected. For a linked law, select Company and Unit first and then click New. The law will be registered and linked automatically.</p><p>A linked law cannot be registered with only Company or only Unit. When duplicating a law, enter a new Code; history, subjects and links are not copied automatically.</p>',
    `texto_es` = '<p>En esta pantalla puede registrar una ley general o una ley vinculada a una empresa y unidad.</p><p>Para una ley general, deje Empresa y Unidad sin seleccionar. Para una ley vinculada, seleccione primero Empresa y Unidad y luego haga clic en Nuevo. La ley se registrará y vinculará automáticamente.</p><p>No es posible registrar una ley vinculada informando solamente Empresa o solamente Unidad. Al duplicar una ley, informe un nuevo Código; el historial, los asuntos y los vínculos no se copian automáticamente.</p>'
WHERE `transacao` = 'manutencaolegal_legislacao';
